#!/usr/bin/env python3
"""Write the website's data module from the JSON that analyze.py --json produced.

  python3 scripts/site_data.py --json site.json --out ../floppydata-landing/src/data/mobileBenchmarkData.ts

Only the Python standard library is used. The output is generated: regenerate it, do not edit it.
"""
import argparse
import json

HEADER = """/*
 * GENERATED by scripts/site_data.py in Floppydata/mobile-proxy-benchmark-2026 from the
 * analyze.py results ({period}); regenerate rather than edit. Rates are %, times are seconds,
 * stickyMedian is minutes. null = not measured yet.{interim}
 */

export const MOBILE_PERIOD = {period_js};
export const MOBILE_INTERIM = {interim_js};

export interface MobileNumbers {{
    successRate: number; requests: number; latencyMedian: number; latencyP90: number;
    latencyByServer: number[]; successByServer: number[]; uniqueIps: number; duplicateRate: number;
    geoAccuracy: number; ipv6Share: number; weakestCountry: string; weakestRate: number;
    googleRate: number | null; instagramRate: number | null;
    stickyMedian: number; sticky10: number; sticky30: number; stickySessions: number;
    fpWindows: number | null; fpEthernet: number | null;
    fraudAvg: number | null; fraudHighRisk: number | null; proxyFlags: number | null; ipSample: number;
    mobileShareIp2l: number | null; mobileShareMaxmind: number | null; sharedIpShare: number | null;
    sharedIpCi: [number, number] | null; googleCi: [number, number] | null; googleCaptcha: number | null;
    googleRequests: number; costPer1k: number | null; price: number; minPurchase: string;
}}

export const mobileNumbers: Record<string, MobileNumbers> = {data};

/** The provider pairs with the most shared exit IPs: shareA/shareB = % of each one's unique IPs,
 * sameHour = % of the shared IPs that both gave out within the same hour. */
export const mobileSharedPairs: {{ a: string; b: string; ips: number; shareA: number; shareB: number; sameHour: number }}[] = {pairs};
"""


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--json", required=True)
    ap.add_argument("--out", required=True)
    ap.add_argument("--final", action="store_true", help="the run is complete (drops the interim flag)")
    a = ap.parse_args()
    d = json.load(open(a.json))
    with open(a.out, "w") as f:
        f.write(HEADER.format(period=d["period"], period_js=json.dumps(d["period"]),
                              interim="" if a.final else " INTERIM: the test was still running.",
                              interim_js="false" if a.final else "true",
                              data=json.dumps(d["providers"], indent=4),
                              pairs=json.dumps(d.get("sharedPairs", []), indent=4)))
    print("Wrote", a.out)


if __name__ == "__main__":
    main()
